System.assertEquals('HALF_UP', RoundingMode.valueOf('HALF_UP').name());
System.assertEquals('HALF_UP', RoundingMode.HALF_UP.toString());
System.assertEquals(0, RoundingMode.UP.ordinal());
System.assertEquals(7, RoundingMode.UNNECESSARY.ordinal());
List<RoundingMode> modes = RoundingMode.values();
System.assertEquals(8, modes.size());
System.assertEquals('UP', modes.get(0).name());
System.assertEquals('UNNECESSARY', modes.get(7).name());

